
.picker {
  width: 100%;
  max-width: 640px;
  margin: 0 auto;
  background: linear-gradient(160deg, #fdf7f2, #fbe4ee 130%);
  border: 2px solid #ecd7e1;
  border-radius: 16px;
  padding: 18px 20px 16px;
  font-family: "Sarasa Mono SC", "Sarasa Gothic SC", "Microsoft YaHei", sans-serif;
  color: #4a3b45;
  box-shadow: 0 4px 18px rgba(232, 126, 164, 0.15);
  text-align: center;
}

.picker-head {
  margin-bottom: 14px;
}

.badge {
  display: inline-block;
  background: #e87ea4;
  color: #fff;
  font-size: 11px;
  padding: 3px 10px;
  border-radius: 999px;
  letter-spacing: 1px;
  margin-bottom: 8px;
}

.picker-title {
  margin: 0;
  font-size: 22px;
  color: #e87ea4;
  letter-spacing: 2px;
}

.picker-sub {
  margin: 6px 0 0;
  font-size: 13px;
  color: #9a8a94;
}

.opening-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
  margin-bottom: 16px;
}

.opening-card {
  position: relative;
  border: 2px solid var(--accent);
  border-radius: 14px;
  padding: 14px 12px 12px;
  background: #fff;
  cursor: pointer;
  text-align: left;
  transition: transform 0.15s ease, box-shadow 0.15s ease;
  font-family: inherit;
}

.opening-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 6px 16px rgba(0, 0, 0, 0.08);
}

.opening-card:disabled {
  opacity: 0.6;
  cursor: default;
}

.op-group {
  position: absolute;
  top: 10px;
  right: 12px;
  font-size: 10px;
  color: var(--accent);
  border: 1px solid var(--accent);
  padding: 1px 7px;
  border-radius: 999px;
}

.op-icon {
  color: var(--accent);
  font-size: 22px;
  margin-bottom: 6px;
}

.op-title {
  margin: 0;
  font-size: 16px;
  color: #4a3b45;
}

.op-sub {
  margin: 5px 0 0;
  font-size: 12px;
  color: #9a8a94;
  line-height: 1.4;
}

.custom-area {
  border-top: 1px dashed #ecd7e1;
  padding-top: 12px;
  margin-bottom: 10px;
}

.divider {
  display: block;
  font-size: 12px;
  color: #9a8a94;
  margin-bottom: 10px;
}

.custom-btn {
  width: 100%;
  padding: 10px;
  border: none;
  border-radius: 10px;
  background: linear-gradient(135deg, #e87ea4, #d4a017);
  color: #fff;
  font-size: 14px;
  font-weight: bold;
  cursor: pointer;
  font-family: inherit;
}

.custom-btn:disabled {
  opacity: 0.6;
  cursor: default;
}

.picker-foot {
  font-size: 11px;
  color: #cbb5bf;
  margin-top: 4px;
}

/* 自定义表单样式 */
.form-card {
  width: 100%;
  max-width: 560px;
  margin: 0 auto;
  text-align: left;
}

.form-title {
  margin: 0 0 4px;
  color: #e87ea4;
  font-size: 20px;
}

.form-sub {
  margin: 0 0 16px;
  font-size: 13px;
  color: #9a8a94;
}

.field {
  margin-bottom: 14px;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.field label {
  font-size: 12px;
  font-weight: bold;
  color: #4a3b45;
}

.field select {
  padding: 8px 10px;
  border: 1.5px solid #ecd7e1;
  border-radius: 8px;
  background: #fdf7f2;
  font-size: 14px;
  color: #4a3b45;
  font-family: inherit;
}

.form-actions {
  display: flex;
  gap: 10px;
  margin-top: 6px;
}

.back-btn,
.submit {
  flex: 1;
  padding: 10px;
  border: none;
  border-radius: 8px;
  font-size: 14px;
  font-weight: bold;
  cursor: pointer;
  font-family: inherit;
}

.back-btn {
  background: #fbe4ee;
  color: #e87ea4;
}

.submit {
  background: linear-gradient(135deg, #e87ea4, #d4a017);
  color: #fff;
}

.back-btn:disabled,
.submit:disabled {
  opacity: 0.6;
  cursor: default;
}

@media (max-width: 520px) {
  .opening-grid {
    grid-template-columns: 1fr;
  }
}
